def verify(w):
    # Fail-closed: any mismatch returns False; only full agreement returns True.
    # No imports, no I/O, no floats, deterministic, exact integer arithmetic only.
    if len(w["cases"]) == 0:
        return False
    vals = {}
    for c in w["cases"]:
        sign = c["sign"]
        exp = c["exp"]
        frac = c["frac"]
        if exp == 0:
            mant = frac
            e = -1074
        else:
            mant = frac + (1 << 52)
            e = exp - 1075
        # exact dyadic value = sign * mant * 2^e
        num = sign * mant
        den = 1
        if e >= 0:
            num = num * (1 << e)
        else:
            den = den * (1 << (-e))
        # cross-multiply against asserted rational exact_num/exact_den
        lhs = num * c["exact_den"]
        rhs = c["exact_num"] * den
        if lhs != rhs:
            return False
        if den <= 0:
            return False
        vals[c["name"]] = (num, den)
    if len(w["comparisons"]) == 0:
        return False
    for k in w["comparisons"]:
        if k["a"] not in vals or k["b"] not in vals:
            return False
        an, ad = vals[k["a"]]
        bn, bd = vals[k["b"]]
        lt = an * bd < bn * ad
        eq = an * bd == bn * ad
        gt = an * bd > bn * ad
        if k["lt"] != lt or k["eq"] != eq or k["gt"] != gt:
            return False
    return True
